const lessons=[{"sentences":[{"speaker":"A","text":"Good morning because I want to swim today I need some information about your pool sessions.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.443125},{"speaker":"B","text":"Good morning and welcome because we have two different swimming slots available this afternoon.","position":2,"audioStartSeconds":5.643125,"audioEndSeconds":11.150708333333334},{"speaker":"A","text":"Could you tell me what the difference is between those two sessions.","position":3,"audioStartSeconds":11.350708333333333,"audioEndSeconds":15.230375},{"speaker":"B","text":"The first one is a quiet adult swim although the second one is a family fun session.","position":4,"audioStartSeconds":15.430375,"audioEndSeconds":20.663083333333333},{"speaker":"A","text":"I would prefer the quiet adult swim because I want to practice my breathing technique.","position":5,"audioStartSeconds":20.863083333333332,"audioEndSeconds":25.966166666666666},{"speaker":"B","text":"That session runs from two until four o clock if you want to book it now.","position":6,"audioStartSeconds":26.166166666666665,"audioEndSeconds":30.779583333333335},{"speaker":"A","text":"That timing suits me perfectly although I need to know how much it costs.","position":7,"audioStartSeconds":30.979583333333334,"audioEndSeconds":35.7605},{"speaker":"B","text":"It costs eight pounds fifty for non members when you pay at the front desk.","position":8,"audioStartSeconds":35.9605,"audioEndSeconds":40.664125},{"speaker":"A","text":"Do I need to bring my own padlock for the changing room lockers.","position":9,"audioStartSeconds":40.864125,"audioEndSeconds":44.987833333333334},{"speaker":"B","text":"You do not need a padlock because our lockers operate with a refundable one pound coin.","position":10,"audioStartSeconds":45.18783333333333,"audioEndSeconds":50.613083333333336},{"speaker":"A","text":"That is very convenient since I always carry loose change in my bag.","position":11,"audioStartSeconds":50.81308333333333,"audioEndSeconds":55.33629166666667},{"speaker":"B","text":"Shall I reserve your place for the afternoon session right now.","position":12,"audioStartSeconds":55.53629166666666,"audioEndSeconds":59.45379166666667},{"speaker":"A","text":"Yes please because I want to make sure I secure a ticket before they sell out.","position":13,"audioStartSeconds":59.65379166666666,"audioEndSeconds":64.48625},{"speaker":"B","text":"I have booked your spot so you can pay and collect your wristband at reception.","position":14,"audioStartSeconds":64.68625,"audioEndSeconds":69.40275},{"speaker":"A","text":"Thank you very much for your kind help with my booking today.","position":15,"audioStartSeconds":69.60275,"audioEndSeconds":73.34533333333333},{"speaker":"B","text":"You are very welcome and we look forward to seeing you at the pool later.","position":16,"audioStartSeconds":73.54533333333333,"audioEndSeconds":78.056875}],"questions":[{"prompt":"What is the primary purpose of the visitor asking questions?","options":["To buy a monthly gym membership.","To gather details about pool sessions and booking.","To complain about the locker prices."],"answer":"B","evidenceSentence":1,"evidence":"I need some information about your pool sessions","explanation":"Người khách bắt đầu bằng việc yêu cầu thông tin về các suất bơi, thể hiện mục đích chính của cuộc trò chuyện."},{"prompt":"Which pool session does the visitor decide to choose?","options":["The quiet adult swim.","The family fun session.","The evening training class."],"answer":"A","evidenceSentence":5,"evidence":"I would prefer the quiet adult swim","explanation":"Khách tham quan chọn suất bơi dành riêng cho người lớn yên tĩnh để tập luyện kỹ thuật thở."},{"prompt":"How much does the session cost for non members?","options":["Five pounds.","Eight pounds fifty.","Ten pounds."],"answer":"B","evidenceSentence":8,"evidence":"It costs eight pounds fifty for non members","explanation":"Nhân viên cho biết chi phí cho người không phải là hội viên là tám bảng năm mươi xu."},{"prompt":"What do visitors need to use the changing room lockers?","options":["A personal padlock.","A membership card.","A refundable one pound coin."],"answer":"C","evidenceSentence":10,"evidence":"our lockers operate with a refundable one pound coin","explanation":"Tủ đồ hoạt động bằng một đồng xu một bảng có thể được hoàn lại, nên khách không cần mang ổ khóa riêng."},{"prompt":"What can be inferred about the visitor from their response regarding loose change?","options":["They never carry coins with them.","They find the locker system convenient.","They prefer paying with a credit card."],"answer":"B","evidenceSentence":11,"evidence":"That is very convenient since I always carry loose change","explanation":"Khách thấy rất tiện lợi vì họ luôn mang theo tiền xu trong túi."},{"prompt":"What will the visitor do next?","options":["Leave the building immediately.","Pay and collect their wristband at reception.","Change into their swimming costume outside."],"answer":"B","evidenceSentence":14,"evidence":"you can pay and collect your wristband at reception","explanation":"Nhân viên đã đặt chỗ xong, bước tiếp theo là khách sẽ thanh toán và nhận vòng đeo tay tại quầy lễ tân."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
